export function measure<T>(label:string,work:()=>T,budget=16):T{
  const start=performance.now();
  const result=work();
  const ms=performance.now()-start;
  if(ms>budget)console.warn(label+": "+ms.toFixed(1)+" ms — powyżej budżetu klatki");
  return result;
}

